
import base64, os, subprocess, sys, shutil
FILES = {"main.tex": "", "references.bib": "", "generated/numbers.tex": "", "generated/tab_block.tex": "", "generated/tab_comparisons.tex": "", "generated/tab_degeneration.tex": "", "generated/tab_dim.tex": "", "generated/tab_exp1_dissociation.tex": "", "generated/tab_exp1_specificity.tex": "", "generated/tab_inventory.tex": "", "generated/tab_layers.tex": "", "generated/tab_penform.tex": "", "generated/tab_qualitative.tex": "", "generated/tab_rescale.tex": "", "generated/tab_sae_quality.tex": "", "generated/tab_sqmean_calib.tex": "", "figures/fig_block.pdf": "", "figures/fig_layers.pdf": "", "figures/fig_penform.pdf": "", "figures/fig_scale.pdf": "", "figures/fig_synthetic.pdf": "", "figures/fig_tradeoff.pdf": ""}
W = "/kaggle/working/paper"
os.makedirs(W, exist_ok=True)
for rel, b in FILES.items():
    p = os.path.join(W, rel)
    os.makedirs(os.path.dirname(p), exist_ok=True)
    open(p, "wb").write(base64.b64decode(b))
print("wrote", len(FILES), "files", flush=True)

pk = ["texlive-latex-base", "texlive-latex-recommended", "texlive-latex-extra",
      "texlive-fonts-recommended", "texlive-science", "texlive-pictures", "lmodern", "latexmk"]
subprocess.run("apt-get update -qq", shell=True)
r = subprocess.run("DEBIAN_FRONTEND=noninteractive apt-get install -y -qq --no-install-recommends "
                   + " ".join(pk), shell=True)
print("apt exit", r.returncode, flush=True)

r = subprocess.run("latexmk -pdf -interaction=nonstopmode -halt-on-error main.tex",
                   shell=True, cwd=W, capture_output=True, text=True)
print("latexmk exit", r.returncode, flush=True)
log = open(os.path.join(W, "main.log"), errors="replace").read() if os.path.exists(os.path.join(W, "main.log")) else ""
for line in log.splitlines():
    if line.startswith("!") or "Warning" in line and ("undefined" in line or "Citation" in line or "Reference" in line):
        print("LOG:", line, flush=True)
print("---- log tail ----")
print(log[-3000:], flush=True)
for f in ("main.pdf", "main.log", "main.blg"):
    if os.path.exists(os.path.join(W, f)):
        shutil.copy(os.path.join(W, f), "/kaggle/working/" + f)
print("pdf present:", os.path.exists("/kaggle/working/main.pdf"), flush=True)
